}

Method.Source:
/// <summary>
/// extends method initFromAgreementLine
/// </summary>
/// <param name = "_agreementLine">AgreementLine</param>
public void initFromAgreementLine(AgreementLine _agreementLine)
{
    next initFromAgreementLine(_agreementLine);

    UnitOfMeasureSymbol agreementLine_UnitId = _agreementLine.inventTable().purchUnitId();
    UnitOfMeasureSymbol purchLine_UnitId = purchLine.inventTable().purchUnitId();

    if(agreementLine_UnitId != purchLine_UnitId)
    {
        purchLine.PurchPrice = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(purchLine.ItemId, purchLine.InventDimId, AgreementLineQuantityCommitment::find(_agreementLine.RecId).PricePerUnit, purchLine_UnitId, agreementLine_UnitId);
    }
}

/// <summary>
/// extends method initFromPurchTable
/// </summary>
/// <param name = "_purchTable">PurchTable</param>
/// <param name = "_ignoreInventDim">boolean</param>
void initFromPurchTable(PurchTable  _purchTable, boolean _ignoreInventDim)
{
    next initFromPurchTable(_purchTable, _ignoreInventDim);

    purchLine.AVAOrderConfirmation = _purchTable.AVAOrderConfirmation;
}

