/// <summary>
/// extension method for inserted
/// </summary>
public void inserted()
{
    InventTable     avaInventTable;

    next inserted();

    if ((this.parmPurchLine().ItemRefType == InventRefType::ProdLine
            || this.parmPurchLine().ItemRefType == InventRefType::Production)
        && this.parmPurchLine().InventRefId)
    {
        avaInventTable = ProdTable::find(this.parmPurchLine().InventRefId).inventTable();

        Docu::KCS_TCVmoduleCopy(avaInventTable, this.parmPurchLine(), AVATCVModule::Purch);
    }
}

public boolean validateWrite()
{
    DimensionAttributeValueSetStorage dimStorage;
    const str costCenter = 'Kostenstellen';
    str costCenterValue;

    boolean ok = next validateWrite();
    if (purchLine.inventTable().itemGroup().AVACostCenterPurchLine)
    {
        dimStorage = DimensionAttributeValueSetStorage::find(purchLine.DefaultDimension);
        costCenterValue = dimStorage.getDisplayValueByDimensionAttribute(DimensionAttribute::findByName(costCenter).RecId);
        if (!costCenterValue)
        {
            ok = checkFailed("@NDX:NXACostCenterPurchLineErr");
        }
    }

    return ok;
}
